examples.code:
-- 중복 키
SELECT COUNT(*) FROM (SELECT order_id FROM orders GROUP BY order_id HAVING COUNT(*) > 1);
-- 고아 키(부모 없는 자식)
SELECT COUNT(*) FROM orders o LEFT JOIN users u ON o.user_id = u.user_id WHERE u.user_id IS NULL;
-- 빠진 날
WITH RECURSIVE d(x) AS (
  SELECT '2026-11-20' UNION ALL SELECT date(x, '+1 day') FROM d WHERE x < '2026-11-22'
)
SELECT group_concat(x) FROM d WHERE x NOT IN (SELECT dt FROM orders);
